const wc = $('When Called').first().json || {};
let ref = wc.surface_ref;
if (typeof ref === 'string') { try { ref = JSON.parse(ref || '{}'); } catch (e) { ref = {}; } }
if (!ref || typeof ref !== 'object') ref = {};
return [{ json: { channel_id: String(ref.channel_id || ''), message_id: String(ref.message_id || '') } }];

const wc = $('When Called').first().json || {};
const ref = $('Parse Surface Ref').first().json || {};
const OPERATOR_ID = '2521617';
const OPERATOR_NAME = 'Franciszek Nowak';

// lane (gates the global-rules fold)
let agent_lane = 'bare';
try { const v = String(($('Read Lane').first().json || {}).agent_lane || '').trim().toLowerCase(); if (v === 'managed' || v === 'bare') agent_lane = v; } catch (e) {}
const isManaged = agent_lane === 'managed';

const reviewer_user_id = String(wc.reviewer_user_id || OPERATOR_ID).trim();
const triggered_by = wc.triggered_by || 'explicit_mention';
const invocation_type = wc.invocation_type || 'explicit';
const triggering_text = String(wc.triggering_comment_text || '').trim();

// resolve member id -> display name
const memberMap = {};
try {
  const teams = (($('Fetch Members').first().json || {}).teams) || [];
  for (const t of teams) { for (const m of (t.members || [])) { const u = m.user || {}; if (u.id != null) memberMap[String(u.id)] = u.username || u.email || ''; } }
} catch (e) {}
let caller_username = String(wc.caller_username || '').trim();
if (!caller_username) caller_username = memberMap[reviewer_user_id] || (reviewer_user_id === OPERATOR_ID ? OPERATOR_NAME : '');

// rules doc pages (flatten)
let pages = [];
try { pages = $('Load Agent Rules').first().json.body || []; } catch (e) {}
const allPages = [];
(function flat(arr){ for (const p of (arr||[])) { allPages.push(p); if (p.pages) flat(p.pages); } })(pages);
const globalPage = allPages.find(p => p.id === 'q7wz-44812');
const global_rules = (globalPage && globalPage.content) ? globalPage.content : '';
const global_rules_missing = isManaged ? false : !global_rules;
const personalPage = caller_username ? allPages.find(p => p.name === ('Instrukcje dla agenta - ' + caller_username)) : null;
const person_rules = (personalPage && personalPage.content) ? personalPage.content : '';
const person_rules_missing = !person_rules;

// thread replies
let replies = [];
try { const rb = ($('Fetch Thread Replies').first().json || {}).body; replies = (rb && rb.data) || []; } catch (e) {}
replies = Array.isArray(replies) ? replies.slice().sort((a,b)=>Number(a.date||0)-Number(b.date||0)) : [];

const lines = [];
if (global_rules && !isManaged) { lines.push('# Zasady ogólne agenta (obowiązują zawsze)'); lines.push(global_rules); lines.push(''); lines.push('---'); lines.push(''); }
if (person_rules) { lines.push('# Preferencje osoby zlecającej (' + caller_username + ')'); lines.push(person_rules); lines.push(''); lines.push('---'); lines.push(''); }

lines.push('# Wiadomość wywołująca tę akcję (czat ClickUp)');
lines.push('Użytkownik ' + (caller_username || ('#' + reviewer_user_id)) + ' napisał na czacie:');
lines.push('---');
lines.push(triggering_text || '[treść wiadomości niedostępna]');
lines.push('---');
lines.push('');
if (replies.length) {
  lines.push('# Wątek — kolejne wiadomości (od najstarszej)');
  for (const r of replies) { const who = memberMap[String(r.user_id)] || ('#' + (r.user_id || '?')); lines.push(who + ': ' + String(r.content || '')); }
  lines.push('');
}

lines.push('# Kontekst');
lines.push('To jest rozmowa na czacie ClickUp (nie zadanie). Nie ma przypisanego zadania ClickUp. Jeśli do odpowiedzi potrzebujesz danych z ClickUp (zadania, dokumenty, komentarze), użyj swoich narzędzi (scoped ClickUp MCP) — masz dostęp w zakresie uprawnień osoby pytającej.');
lines.push('');
lines.push('# Format odpowiedzi (OBOWIĄZKOWY)');
lines.push('Zwróć WYŁĄCZNIE tablicę JSON bloków typu text — bez tekstu przed i po, bez ogrodzenia markdown:');
lines.push('  { "type": "text", "md": "…treść markdown po polsku…" }');
lines.push('Odpowiadaj zwięźle i konwersacyjnie (to czat, nie formalny komentarz do zadania). Całą treść umieść w blokach text (markdown: listy, pogrubienia, krótkie nagłówki gdy potrzebne). Nie dodawaj sekcji „Pytania do zlecającego/Decyzje/Sugestie do procesu” typowych dla zadań, chyba że pasują. Jeśli obrazy są potrzebne — w tej wersji czatu zwróć opis tekstowy (dostarczanie obrazów na czacie będzie później).');
lines.push('Przykład: [{"type":"text","md":"Cześć! Oto co znalazłem: …"}]');

const prompt = lines.join('\n');

return [{ json: {
  prompt,
  agent_lane,
  impact: 'Średni',
  modality: 'text',
  task_type: '',
  clickup_task_id: '',
  triggered_by,
  invocation_type,
  reviewer_user_id,
  caller_user_id: reviewer_user_id,
  caller_username,
  process_type: '',
  assignee_user_id: '',
  creator_user_id: '',
  triggering_comment_id: '',
  web_sources: '[]',
  image_blocks_json: '[]',
  input_warnings_json: '[]',
  input_warnings_count: 0,
  surface: 'chat',
  surface_ref: JSON.stringify({ channel_id: ref.channel_id || '', message_id: ref.message_id || '' }),
  global_rules_missing,
  person_rules_missing
} }];
